import axios from 'axios';

const API_BASE_URL = 'http://localhost:5000/api'; // Ajusta esto a la URL de tu backend

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

export const loginUser = async (credentials) => { // <--- **VERIFICA ESTA EXPORTACIÓN**
  try {
    const response = await api.post('/auth/login', credentials);
    return response.data;
  } catch (error) {
    throw error.response ? error.response.data : error;
  }
};

// Si tienes otras funciones en api.js, asegúrate de que también estén exportadas correctamente.
